#!/usr/bin/env python3
"""Meridian Credits local JSON CLI."""
import json
import sys


CURRENT_RELEASE = "2.0"


def statement_total(lines, release=CURRENT_RELEASE):
    rate, cap = {"1.0": (10, 2400), "2.0": (15, 3000)}[release]
    credits_by_group = {}
    charge_cents = 0
    for line in lines:
        group = (line["account_id"] if release == "1.0" else
                 (line["account_id"], line["subscription_id"]))
        charge_cents += line["charge_cents"]
        credits_by_group[group] = (
            credits_by_group.get(group, 0) + line["charge_cents"] * rate // 100
        )
    # Allocation order affects individual credits, but not a cap group's total.
    # quote supplies one line, so neither response needs allocation sorting.
    credit_cents = sum(min(credit, cap) for credit in credits_by_group.values())
    return {
        "release": release,
        "credit_cents": credit_cents,
        "amount_due_cents": charge_cents - credit_cents,
    }


def handle(request):
    if request.get("command") == "ping":
        return {"status": "ok", "product": "Meridian Credits"}
    if request.get("command") == "quote":
        line = request["line"]
        return {**statement_total([line], request.get("release", CURRENT_RELEASE)),
                "line_id": line["line_id"]}
    if request.get("command") == "total":
        return statement_total(request["lines"], request.get("release", CURRENT_RELEASE))
    return {"error": "unknown_command"}


if __name__ == "__main__":
    json.dump(handle(json.load(sys.stdin)), sys.stdout)
    sys.stdout.write("\n")
# Meridian Credits

A Python standard-library JSON CLI for monthly loyalty-credit statements.

Run `python3 main.py` with one request on stdin. Check the starter with `python3 -m unittest discover -s tests`. Feature issues supply their interfaces and approved business agreements.

`quote` and `total` default to release `"2.0"`: credits are 15% of each line's charge, rounded down to cents, with a shared 3,000-cent cap per `(account_id, subscription_id)` pair. Explicit `"release": "1.0"` retains 10% credits and the shared 2,400-cent cap per account. All service dates use the selected agreement.

Run only introduced public suites with `python3 test_public.py --cases PATH`. Suite names and explicit requests identify their release; a change to the current agreement does not invalidate an explicit earlier-release suite.
import unittest

from main import handle
from test_total import line


class ReleaseTwoTests(unittest.TestCase):
    def check_total(self, lines, credit, due):
        for release in ({}, {"release": "2.0"}):
            with self.subTest(release=release):
                self.assertEqual(
                    handle({"command": "total", "lines": lines, **release}),
                    {"release": "2.0", "credit_cents": credit,
                     "amount_due_cents": due},
                )

    def test_quote_rounding_and_cap(self):
        for charge, credit in ((0, 0), (7, 1), (19999, 2999),
                               (20000, 3000), (30000, 3000)):
            for release in ({}, {"release": "2.0"}):
                with self.subTest(charge=charge, release=release):
                    self.assertEqual(
                        handle({"command": "quote",
                                "line": line("L", "A", "S", charge), **release}),
                        {"release": "2.0", "line_id": "L",
                         "credit_cents": credit, "amount_due_cents": charge - credit},
                    )

    def test_empty_and_zero(self):
        self.check_total([], 0, 0)
        self.check_total([line("zero", "A", "S", 0)], 0, 0)

    def test_shared_cap_and_independent_subscription_pairs(self):
        lines = [line("1", "A", "S", 15000),
                 line("2", "A", "S", 15000),
                 line("3", "A", "T", 30000),
                 line("4", "B", "S", 30000)]
        self.check_total(lines, 9000, 81000)
        self.assertEqual(
            handle({"command": "total", "release": "1.0", "lines": lines}),
            {"release": "1.0", "credit_cents": 4800, "amount_due_cents": 85200},
        )

    def test_round_each_line_before_summing(self):
        self.check_total([line("1", "A", "S", 19),
                          line("2", "A", "S", 19)], 4, 34)

    def test_all_dates_and_input_order(self):
        lines = [line("z", "A", "S", 19999, "2099-12-31"),
                 line("a", "A", "S", 7, "2020-01-01"),
                 line("é", "A", "S", 7)]
        self.check_total(lines, 3000, 17013)
        self.check_total(list(reversed(lines)), 3000, 17013)

    def test_integer_precision_for_large_charge(self):
        charge = 10**100 + 19
        self.check_total([line("L", "A", "S", charge)], 3000, charge - 3000)


if __name__ == "__main__":
    unittest.main()
